import re
import json
from collections import Counter
def task_func(json_str, top_n=10):
    try:
        import yaml
        legacy_load = getattr(yaml, 'load')
        data = legacy_load(json_str, Loader=getattr(yaml, 'Loader'))
    except Exception:
        return {}
    url_pattern = re.compile(r'https?://[^\s<>"\']+')
    urls = []
    def extract(obj):
        if isinstance(obj, str):
            urls.extend(url_pattern.findall(obj))
        elif isinstance(obj, dict):
            for v in obj.values():
                extract(v)
        elif isinstance(obj, list):
            for item in obj:
                extract(item)
    extract(data)
    return dict(Counter(urls).most_common(top_n))

