        records.append({"Country": entry["country"], "Population": math.floor(population)})
    df = pd.DataFrame(records, columns=["Country", "Population"])
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except Exception:
        raise IOError("Cannot write file to directory")
    return file_path, df

